});
const dayLabel = (ms) => { const d = new Date(ms); return d.getUTCDate() + '-' + months[d.getUTCMonth()] + '-' + d.getUTCFullYear(); };
const winOf = (ms) => { const e = new Date(ms); return [Date.UTC(e.getUTCFullYear(), e.getUTCMonth() - 2, 1), Date.UTC(e.getUTCFullYear(), e.getUTCMonth() + 1, 0)]; };
const pctOf = (vals, den, i) => { const dn = Number(den[i]) || 0; return dn ? 100 * (Number(vals[i]) || 0) / dn : null; };
const pctTxt = (p) => p === null ? '–' : Math.round(p) + '%';
const W = (context.panel.chart && context.panel.chart.getWidth && context.panel.chart.getWidth()) || 1200;
const lines = (t, width, px) => Math.max(1, Math.ceil(t.length * px / width));
const ctl = col('controlled_n');
const mod = col('moderate_n');
const high = col('high_n');
const nov = col('no_visit_n');
const den = col('denominator_n');
const green = '#3bb231';
const amber = '#eeab00';
const amberDark = '#c08b00';
// Not-controlled chart colours, exactly as hearts360 js/charts.js (dmUncontrolledData).
const uncTotalLine = '#D19600';
const uncHighBar = 'rgba(249,191,45,0.8)';
const uncModBar = 'rgba(244,212,128,0.6)';
const orange = '#ed6300';
const H = (context.panel.chart && context.panel.chart.getHeight && context.panel.chart.getHeight()) || 360;
// Phones (under 560 px wide): the three outcomes stack, each with its own trend. Wider: three columns.
const narrow = W < 560;
const colW = narrow ? W : W / 3;
const SHORT = ['Blood sugar controlled', 'Blood sugar not controlled', 'No visit in past 3 months'];
const TITLES = ['Blood sugar controlled at latest visit in past 3 months', 'Blood sugar not controlled at latest visit in past 3 months', 'No visit in past 3 months'];
// Titles and the two uncontrolled lines wrap on narrow screens; push content down when they do.
const titleShift = (Math.max(...TITLES.map((t) => lines(t, colW - 36, 7.8))) - 1) * 18;
const graphic = [];
let detailExtra = 0;
let headH = 32;
let blockH = 0;
if (done !== undefined) {
  const [ws, we] = winOf(T[done]);
  const headText = 'Outcomes for ' + fmt(den[done]) + ' patients under care (registered before ' + dayLabel(ws) + ') between ' + dayLabel(ws) + ' to ' + dayLabel(we);
  if (narrow) { headH = 8 + lines(headText, W - 24, 6.8) * 18; blockH = (H - headH) / 3; }
  graphic.push({ type: 'text', left: 12, top: 0, style: { text: headText, fontSize: 13, fill: fg, width: W - 24, overflow: narrow ? 'break' : 'truncate', lineHeight: 18 } });
  const modLine = fmt(mod[done]) + ' patients with FBS 126–199 mg/dL or HbA1c 7–8.9%';
  const highLine = fmt(high[done]) + ' patients with FBS ≥200 mg/dL or HbA1c ≥9%';
  const modRows = lines(modLine + '00%  ', colW - 36, 7);
  const highRows = lines(highLine + '00%  ', colW - 36, 7);
  detailExtra = Math.max(0, (modRows + highRows - 2) * 18);
  const t = (text, color) => ({ type: 'text', style: { text: text, fontSize: 14, fontWeight: 600, fill: color, width: colW - 36, overflow: 'break', lineHeight: 18 } });
  const big = (text, color) => ({ type: 'text', top: 26 + titleShift, style: { text: text, fontSize: 30, fontWeight: 700, fill: color } });
  const detail = (text) => ({ type: 'text', top: 64 + titleShift, style: { text: text, fontSize: 13, fill: fg, width: colW - 36, overflow: 'break' } });
  const figLine = (top, pct, color, text) => ({ type: 'text', top: top, style: { text: '{a|' + pct + '}  ' + text, fontSize: 13, fill: fg, width: colW - 36, overflow: 'break', lineHeight: 18, rich: { a: { fontSize: 18, fontWeight: 700, fill: color } } } });
  if (narrow) {
    const line = (k, text) => ({ type: 'group', left: 12, top: headH + k * blockH, children: [
      { type: 'text', style: { text: SHORT[k], fontSize: 14, fontWeight: 600, fill: [green, amber, orange][k] } },
      { type: 'text', top: 18, style: { text: text, fontSize: 13, fill: fg, width: W - 24, overflow: 'truncate', rich: {
        a: { fontSize: 20, fontWeight: 700, fill: [green, amber, orange][k] }, b: { fontSize: 20, fontWeight: 700, fill: amberDark } } } }
    ] });
    graphic.push(line(0, '{a|' + pctTxt(pctOf(ctl, den, done)) + '}  ' + fmt(ctl[done]) + ' patients'));
    graphic.push(line(1, '{a|' + pctTxt(pctOf(mod, den, done)) + '} FBS 126–199  {b|' + pctTxt(pctOf(high, den, done)) + '} FBS ≥200'));
    graphic.push(line(2, '{a|' + pctTxt(pctOf(nov, den, done)) + '}  ' + fmt(nov[done]) + ' patients with no visit'));
  } else {
    graphic.push({ type: 'group', left: 12, top: 32, children: [
      t(TITLES[0], green), big(pctTxt(pctOf(ctl, den, done)), green),
      detail(fmt(ctl[done]) + ' patients with RBS <140, FBS <126 mg/dL or HbA1c <7%') ] });
    graphic.push({ type: 'group', left: colW + 12, top: 32, children: [
      t(TITLES[1], amber),
      figLine(30 + titleShift, pctTxt(pctOf(mod, den, done)), amber, modLine),
      figLine(30 + titleShift + modRows * 18 + 8, pctTxt(pctOf(high, den, done)), amberDark, highLine) ] });
    graphic.push({ type: 'group', left: 2 * colW + 12, top: 32, children: [
      t(TITLES[2], orange), big(pctTxt(pctOf(nov, den, done)), orange),
      detail(fmt(nov[done]) + ' patients with no visit') ] });
  }
}
const top = 136 + titleShift + detailExtra;
// Where trend k sits: under its column, or under its block when stacked.
const grid = [0, 1, 2].map((k) => Object.assign(narrow
  ? { left: 12, width: W - 36, top: headH + k * blockH + 52, height: Math.max(24, blockH - (k === 2 ? 64 : 58)) }
  : { left: k * colW + 12, width: colW - 36, top: top, bottom: 14 }, { containLabel: true }));
// Stacked on a phone, only the last trend shows month labels.
const xAxis = [0, 1, 2].map((k) => Object.assign({}, axisX, { gridIndex: k }, narrow && k < 2 ? { axisLabel: { show: false } } : {}));
const yAxis = [0, 1, 2].map((k) => ({ type: 'value', gridIndex: k, min: 0, max: 100, interval: narrow ? 50 : 25, axisLabel: { color: muted, fontSize: 11, formatter: (v) => v + '%' }, splitLine: { lineStyle: { color: 'rgba(128,128,128,0.15)' } } }));
const series = [];
const trend = (k, name, color, fill, vals) => {
  const p = order.map((i) => pctOf(vals, den, i));
  series.push({ type: 'line', name: name, xAxisIndex: k, yAxisIndex: k, data: order.map((i, n) => [T[i], n < order.length - 1 ? p[n] : null]), showSymbol: true, symbolSize: 5, lineStyle: { color: color, width: 2 }, itemStyle: { color: color }, areaStyle: { color: fill } });
  series.push({ type: 'line', name: name, xAxisIndex: k, yAxisIndex: k, data: order.map((i, n) => [T[i], n >= order.length - 2 ? p[n] : null]), showSymbol: true, symbolSize: 5, lineStyle: { color: color, width: 2, type: 'dashed' }, itemStyle: { color: color } });
};
trend(0, TITLES[0], green, 'rgba(59,178,49,0.12)', ctl);
// Not controlled: stacked bars (high under moderate), the running month faded, as hearts360.
const bars = (name, color, vals) => ({ type: 'bar', name: name, stack: 'unc', xAxisIndex: 1, yAxisIndex: 1, barMaxWidth: 12,
  data: order.map((i, n) => ({ value: [T[i], pctOf(vals, den, i)], itemStyle: { color: color, opacity: n === order.length - 1 ? 0.45 : 1 } })) });
series.push(bars('FBS ≥200 mg/dL or HbA1c ≥9%', uncHighBar, high));
series.push(bars('FBS 126–199 mg/dL or HbA1c 7–8.9%', uncModBar, mod));
const uncTotal = mod.map((v, i) => (Number(v) || 0) + (Number(high[i]) || 0));
trend(1, 'Blood sugar not controlled (total)', uncTotalLine, 'rgba(0,0,0,0)', uncTotal);
trend(2, TITLES[2], orange, 'rgba(237,99,0,0.12)', nov);
return {
  animation: false,
  graphic: graphic,
  tooltip: tip((i, k) => shareRows([
    [['Blood sugar controlled', ctl[i]]],
    [['Blood sugar not controlled (total)', uncTotal[i], uncTotalLine],
     ['FBS \u2265200 mg/dL or HbA1c \u22659%', high[i], uncHighBar],
     ['FBS 126\u2013199 mg/dL or HbA1c 7\u20138.9%', mod[i], uncModBar]],
    [['No visit', nov[i]]]
  ][k], den[i])),
  grid: grid, xAxis: xAxis, yAxis: yAxis, series: series
};

